import sys, optax
sys.path.append('storage/ariadne')

from models_fourier_ramp import create_network, export_stats
from losses import mae_with_temporal_curvature

BASE_SEED = 42
BATCH_SIZE = 8

def _define_hyperparameters():
    return {
        'learning_rate': 9e-4,
        'rank_k': 320,
        'proj_rank': 36,
        'hidden_size': 152,
        'drop': 0.05,
        'gamma_start': 0.25,
        'gamma_end': 0.99,
        'learn_gamma': False
    }

def compute_loss(predictions, targets, params, x):
    return mae_with_temporal_curvature(predictions, targets, params, x, lam=1e-4)

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adam(learning_rate=learning_rate)
    )

def complete(params, opt_state, trial_data):
    export_stats(params, trial_data, _define_hyperparameters(), out_dir="storage/ariadne/analyses/fourier_ramp_sweep_H152")
